  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// SQLite não suporta enums nativos\n// Valores possíveis para role: ADMIN, ATTENDANT, VIEWER\n// Valores possíveis para status: OPEN, IN_PROGRESS, RESOLVED, CLOSED, CANCELLED\n// Valores possíveis para priority: LOW, MEDIUM, HIGH, URGENT\n\nmodel User {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  password  String\n  name      String\n  role      String   @default(\"ATTENDANT\") // ADMIN, ATTENDANT, VIEWER\n  active    Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  assignedTickets Ticket[] @relation(\"AssignedTickets\")\n\n  @@map(\"users\")\n}\n\nmodel Client {\n  id        String   @id @default(uuid())\n  name      String\n  email     String?\n  phone     String?\n  document  String?  @unique // CPF/CNPJ\n  address   String?\n  active    Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tickets Ticket[]\n\n  @@map(\"clients\")\n}\n\nmodel Category {\n  id          String   @id @default(uuid())\n  name        String   @unique\n  description String?\n  color       String? // Hex color for UI\n  active      Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  tickets Ticket[]\n  slas    SLA[]\n\n  @@map(\"categories\")\n}\n\nmodel SLA {\n  id             String   @id @default(uuid())\n  name           String\n  categoryId     String?\n  responseTime   Int // Em minutos\n  resolutionTime Int // Em minutos\n  priority       String   @default(\"MEDIUM\") // LOW, MEDIUM, HIGH, URGENT\n  active         Boolean  @default(true)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  category Category? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n  tickets  Ticket[]\n\n  @@map(\"slas\")\n}\n\nmodel Ticket {\n  id          String @id @default(uuid())\n  title       String\n  description String\n  status      String @default(\"OPEN\") // OPEN, IN_PROGRESS, RESOLVED, CLOSED, CANCELLED\n  priority    String @default(\"MEDIUM\") // LOW, MEDIUM, HIGH, URGENT\n\n  clientId     String\n  categoryId   String\n  slaId        String?\n  assignedToId String?\n\n  telegramUserId String? // ID do usuário no Telegram\n  telegramChatId String? // ID do chat no Telegram\n\n  responseDeadline   DateTime? // Prazo para primeira resposta\n  resolutionDeadline DateTime? // Prazo para resolução\n\n  respondedAt DateTime? // Quando foi respondido\n  resolvedAt  DateTime? // Quando foi resolvido\n  closedAt    DateTime? // Quando foi fechado\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  client     Client   @relation(fields: [clientId], references: [id])\n  category   Category @relation(fields: [categoryId], references: [id])\n  sla        SLA?     @relation(fields: [slaId], references: [id], onDelete: SetNull)\n  assignedTo User?    @relation(\"AssignedTickets\", fields: [assignedToId], references: [id], onDelete: SetNull)\n\n  comments TicketComment[]\n  history  TicketHistory[]\n\n  @@map(\"tickets\")\n}\n\nmodel TicketComment {\n  id         String   @id @default(uuid())\n  ticketId   String\n  userId     String?\n  content    String\n  isInternal Boolean  @default(false) // Comentário interno (não visível ao cliente)\n  createdAt  DateTime @default(now())\n\n  ticket Ticket @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n\n  @@map(\"ticket_comments\")\n}\n\nmodel TicketHistory {\n  id        String   @id @default(uuid())\n  ticketId  String\n  userId    String?\n  action    String // Ex: \"Status alterado\", \"Atribuído a\", \"Prioridade alterada\"\n  oldValue  String?\n  newValue  String?\n  createdAt DateTime @default(now())\n\n  ticket Ticket @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n\n  @@map(\"ticket_history\")\n}\n",
